mapper.select:
SELECT
    trace_id,
    last_seen_at,
    last_audit_id
FROM governance_history_lookup_index
WHERE tenant_id = #{tenantId}
  AND lookup_type = #{lookupType}
  AND lookup_id = #{lookupId}

    AND last_seen_at >= #{windowStart}


    AND last_seen_at <= #{windowEnd}


    AND (
      last_seen_at < #{cursorCreatedAt}
      OR (last_seen_at = #{cursorCreatedAt} AND last_audit_id < #{cursorAuditId})
    )

ORDER BY last_seen_at DESC, last_audit_id DESC
LIMIT #{limit}
